css:
@font-face { font-family: 'XiaolaiMono'; src: url('https://pub-9cfdbb4d14064a6dbe0397ffdff85f4b.r2.dev/font/XiaolaiMono-Regular.woff2') format('woff2'); font-display: swap; }
.phone { --avatar-size: 34px; --message-gap: 9px; background: linear-gradient(180deg, #F3DDE5 0%, #EFD7E1 48%, #E8CFDA 100%); border: 1px solid #DDBFCB; box-shadow: inset 0 0 0 3px #FFFFFFA8, inset 0 0 0 5px #FFFFFF38, 0 12px 30px #A9788D22; }
.phone .phone-screen { background-color: #FFF9FB; background-image: radial-gradient(circle at 18px 18px, #EECED81F 1px, transparent 1.5px), radial-gradient(circle at 4px 6px, #F3DDE51A 1px, transparent 1.5px), linear-gradient(180deg, #FFFDFE 0%, #FFF8FA 100%); background-size: 24px 24px, 30px 30px, 100% 100%; border: 1px solid #F7E7EC; box-shadow: inset 0 0 22px #EBCDD814; }
.phone .phone-status { color: #8C737D; font-family: 'XiaolaiMono', 'PingFang SC', system-ui, sans-serif; }
.phone .phone-island { background: #6A5A61; box-shadow: 0 2px 5px #8A667420; }
.phone .phone-battery { border-color: #9D7F8A; }
.phone .phone-battery::before { background: #DDAFBD; }
.phone .phone-header { font-family: 'XiaolaiMono', 'PingFang SC', system-ui, sans-serif; color: #65555C; background: #FFFDFED9; border-bottom: 1px solid #EEDCE3; box-shadow: 0 3px 12px #CFA8B316; backdrop-filter: blur(6px); }
.phone .phone-contact { font-weight: 600; letter-spacing: 0.02em; }
.phone .phone-back { color: #B88F9E; }
.phone .messages { scrollbar-color: #D9B8C4 transparent; padding-top: 12px; padding-bottom: 14px; }
.phone .messages::-webkit-scrollbar { width: 5px; }
.phone .messages::-webkit-scrollbar-thumb { background: #D9B8C4B8; border-radius: 999px; }
.phone .message-avatar { border-radius: 12px; border: 2px solid #FFFFFF; box-shadow: 0 2px 8px #B9899924, 0 0 0 1px #E5C9D2; background-color: #F6E9ED; }
.phone .own .message-avatar { border-radius: 12px; border-color: #FFFDFE; box-shadow: 0 2px 8px #BA8C9A24, 0 0 0 1px #E1BCC8; }
.phone .bubble { font-family: 'XiaolaiMono', 'PingFang SC', system-ui, sans-serif; font-size: 14px; line-height: 1.72; color: #5C5056; overflow-wrap: anywhere; }
.phone .message[data-type=text] .bubble { background: #FFFDFEF2; border: 1px solid #EEDDE3; border-radius: 15px 15px 15px 6px; padding: 9px 12px; box-shadow: 0 3px 10px #B9869620; }
.phone .message.own[data-type=text] .bubble { background: #F8E9EEF5; border-color: #E5C6D1; border-radius: 15px 15px 6px 15px; box-shadow: 0 3px 10px #B9869624; }
.phone .message-time { color: #A1848F; opacity: 0.92; font-family: 'XiaolaiMono', 'PingFang SC', system-ui, sans-serif; font-size: 10px; letter-spacing: 0.02em; }
.phone .voice { font-family: 'XiaolaiMono', 'PingFang SC', system-ui, sans-serif; }
.phone .message[data-type=voice] .bubble { background: #FFFDFEF2; border: 1px solid #EEDDE3; border-radius: 15px 15px 15px 6px; padding: 0; overflow: hidden; box-shadow: 0 3px 10px #B9869620; }
.phone .message.own[data-type=voice] .bubble { background: #F8E9EEF5; border-color: #E5C6D1; border-radius: 15px 15px 6px 15px; }
.phone .voice-bar { color: #6C5861; padding: 9px 12px; }
.phone .voice-wave i { background: #D7A7B6; border-radius: 999px; }
.phone .own .voice-wave i { background: #C58FA1; }
.phone .voice-hint { color: #A3818D; font-size: 11px; }
.phone .voice-transcript { color: #67575E; background: #FFF8FAB8; border-top: 1px dashed #E7CDD6; padding: 9px 12px 10px; font-size: 13px; line-height: 1.75; }
.phone .transfer-card { background: linear-gradient(145deg, #E7B8C4 0%, #DFA8B8 100%); color: #FFFDFE; border: 1px solid #D49DAC; border-radius: 17px; box-shadow: 0 6px 14px #B57E9028; overflow: hidden; }
.phone .transfer-main { padding: 14px 15px 11px; }
.phone .transfer-main strong { color: #FFFFFF; font-family: 'XiaolaiMono', 'PingFang SC', system-ui, sans-serif; font-size: 21px; font-weight: 600; }
.phone .transfer-note { color: #FFF7F9; opacity: 0.95; }
.phone .transfer-foot { background: #FFFDFEF0; color: #A27685; border-top: 1px solid #FFFFFF80; font-family: 'XiaolaiMono', 'PingFang SC', system-ui, sans-serif; }
.phone .image-description { background: #FFFDFEF2; color: #7A646D; border: 1px dashed #E7C9D3; border-radius: 14px; padding: 12px; font-family: 'XiaolaiMono', 'PingFang SC', system-ui, sans-serif; line-height: 1.7; }
.phone .message-image { border-radius: 16px; box-shadow: 0 5px 14px #A9788A24; border: 2px solid #FFFDFE; }
.phone .sticker-built-in, .phone .sticker-image { filter: drop-shadow(0 4px 6px #B88C9920); }
.phone .sticker-fallback { color: #866C76; background: #FFF7FACF; border: 1px dashed #E7CBD4; border-radius: 13px; padding: 8px 10px; font-family: 'XiaolaiMono', 'PingFang SC', system-ui, sans-serif; }
.phone .location-card { background: #FFFDFEF2; border: 1px solid #E6CBD4; border-radius: 17px; overflow: hidden; box-shadow: 0 5px 14px #A9788A20; }
.phone .location-caption { background: #FFF9FBE8; padding: 10px 12px; color: #68565E; }
.phone .location-caption strong { color: #5C4B52; font-family: 'XiaolaiMono', 'PingFang SC', system-ui, sans-serif; }
.phone .location-caption small { color: #A0808B; }
.phone .virtual-map { background: linear-gradient(135deg, #FCEFF3 0%, #F3E4EC 52%, #EEF1EA 100%); }
.phone .share-card { background: #FFFDFEF2; border: 1px solid #E7CDD6; border-radius: 17px; box-shadow: 0 5px 14px #A9788A1F; overflow: hidden; color: #66555C; }
.phone .share-card strong { color: #584950; font-family: 'XiaolaiMono', 'PingFang SC', system-ui, sans-serif; }
.phone .share-description { color: #856D76; line-height: 1.65; }
.phone .share-thumbnail { background: #FAEEF2; border-radius: 11px; }
.phone .share-source { color: #A07F8A; border-top-color: #EFDCE2; font-family: 'XiaolaiMono', 'PingFang SC', system-ui, sans-serif; }
.phone .call-record, .phone .message[data-type=call] .bubble, .phone .message[data-type=video] .bubble { color: #806873; font-family: 'XiaolaiMono', 'PingFang SC', system-ui, sans-serif; }
.phone .message[data-type=call] .call-record, .phone .message[data-type=video] .call-record { background: #FFF9FBE8; border: 1px solid #E9D3DA; border-radius: 999px; box-shadow: 0 3px 9px #B98A9920; }
.phone .phone-footer { background: #FFFDFEE6; border-top: 1px solid #EEDCE3; backdrop-filter: blur(6px); }
.phone .phone-input { background: #FFF9FB; color: #A48691; border: 1px solid #E6CDD6; border-radius: 999px; box-shadow: inset 0 1px 4px #BD91A015; font-family: 'XiaolaiMono', 'PingFang SC', system-ui, sans-serif; }
.phone .phone-home { background: #806B74; opacity: 0.55; border-radius: 999px; }
@media (max-width: 300px) { .phone { --avatar-size: 31px; --message-gap: 7px; } .phone .bubble { font-size: 13px; } .phone .message[data-type=text] .bubble { padding: 8px 10px; } .phone .transfer-main strong { font-size: 19px; } }
